import java.util.ArrayList;
import java.util.List;

public class PlaylistApp {
    public static void main(String[] args) {
        List<Song> playlist = new ArrayList<>();

        playlist.add(new Song("Midnight City", "M83", "Electronic", 8));
        playlist.add(new Song("Weightless", "Marconi Union", "Ambient", 2));
        playlist.add(new Song("Thunderstruck", "AC/DC", "Rock", 10));

        System.out.println("Playlist (" + playlist.size() + " songs):");
        for (Song song : playlist) {
            System.out.println("  " + song);
        }
    }
}
